int _read(int file, char *ptr, int len) {
    UNUSED(file);
    UNUSED(len);
    /* One character at a time, echoed back so the terminal shows what is typed. */
    if (HAL_UART_Receive(&huart2, (uint8_t *)ptr, 1, HAL_MAX_DELAY) != HAL_OK) return 0;
    HAL_UART_Transmit(&huart2, (uint8_t *)ptr, 1, HAL_MAX_DELAY);
    return 1;
}

