// 16x2 문자 LCD
// 1: VSS, 2: VDD, 3: VO, 4: RS, 5: R/W, 6: E, 7: D0, 8: D1, 9: D2, 10: D3, 11: D4, 12: D5, 13: D6, 14: D7, 15: A, 16: K
#include "main.h"
#include "usart.h"
#include "gpio.h"
#include <stdio.h>

/* USER CODE BEGIN Includes */
/* USER CODE END Includes */

/* Copy this main.c into a CubeIDE STM32F446RE project with matching
 * pin / peripheral / NVIC settings and Cube-generated IRQ / MSP files.
 * Clock: HSI direct (PLL off), APB1 timer clock = 16000000 Hz.
 * printf / scanf: USART2 (ST-LINK virtual COM port) through _write / _read below.
 * With newlib-nano, enable -u _printf_float for floating-point printf. */

/* USER CODE BEGIN PV */
/* USER CODE END PV */

void SystemClock_Config(void);
void Error_Handler(void);

/* USER CODE BEGIN 0 */
// VSS/VO/RW/K→GND, VDD→5V, A→220 Ω→5V · RS PB0, E PB1, DB4~7 PB4~7 · DB0~3 미연결
void lcdNibble(uint8_t value) {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_4, (value & 1) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_5, (value & 2) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_6, (value & 4) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_7, (value & 8) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_SET);
    HAL_Delay(1);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_1, GPIO_PIN_RESET);
    HAL_Delay(1);
}
void lcdSend(uint8_t value, uint8_t data) {
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0, data ? GPIO_PIN_SET : GPIO_PIN_RESET);
    lcdNibble(value >> 4);
    lcdNibble(value & 15);
    HAL_Delay(2);
}
void lcdPrint(char text[]) {
    for (int i = 0; text[i] != 0; i++) lcdSend(text[i], 1);
}
/* USER CODE END 0 */

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_USART2_UART_Init();
    /* USER CODE BEGIN 2 */
    HAL_Delay(20);
    lcdNibble(3);
    HAL_Delay(5);
    lcdNibble(3);
    lcdNibble(3);
    lcdNibble(2);
    lcdSend(0x28, 0);
    lcdSend(0x0C, 0);
    lcdSend(0x06, 0);
    lcdSend(0x01, 0);
    char line1[] = "STM Emulator";
    char line2[] = "HAL 4-bit LCD";
    lcdPrint(line1);
    lcdSend(0xC0, 0);
    lcdPrint(line2);
    /* USER CODE END 2 */
    while (1) {
        /* USER CODE BEGIN 3 */
        HAL_Delay(100);
        /* USER CODE END 3 */
    }
}

