    while (1) {
        /* USER CODE BEGIN 3 */
        uint8_t frame[9]={0};
        uint32_t grb=ws2812Colors[ws2812Index%4];
        for (uint32_t bit=0;bit<24;bit++) {
            uint32_t symbol=(grb&(1UL<<(23-bit)))?6:4;
            for (uint32_t b=0;b<3;b++) {
