/* USER CODE BEGIN Includes */
/* USER CODE END Includes */

/* Copy this main.c into a CubeIDE STM32F446RE project with matching
 * pin / peripheral / NVIC settings and Cube-generated IRQ / MSP files.
 * Clock: HSI PLL, APB1 timer clock = 84000000 Hz.
 * printf / scanf: USART2 (ST-LINK virtual COM port) through _write / _read below.
 * With newlib-nano, enable -u _printf_float for floating-point printf. */

/* USER CODE BEGIN PV */
// HC-SR04 TRIG→PC7, ECHO→1 kΩ / 2 kΩ 분압→PA9, 5V/GND · TIM2 1 MHz, 0.1 ms 폴링
uint32_t phase = 0, started = 0, echoStarted = 0;
/* USER CODE END PV */

void SystemClock_Config(void);
void Error_Handler(void);

/* USER CODE BEGIN 0 */
/* USER CODE END 0 */

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_TIM2_Init();
    MX_USART2_UART_Init();
    /* USER CODE BEGIN 2 */
    HAL_TIM_Base_Start(&htim2);
    /* USER CODE END 2 */
    while (1) {
        /* USER CODE BEGIN 3 */
        uint32_t now = __HAL_TIM_GET_COUNTER(&htim2);
        if (phase == 0) {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_7, GPIO_PIN_SET);
            started = now;
            phase = 1;
        }
        else if (phase == 1 && (uint32_t)(now - started) >= 10) {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_7, GPIO_PIN_RESET);
            started = now;
            phase = 2;
        }
        else if (phase == 2) {
            if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_9) == GPIO_PIN_SET) {
                echoStarted = now;
                phase = 3;
            }
            else if ((uint32_t)(now - started) >= 30000) {
                printf("HC-SR04 timeout\n");
                phase = 4;
            }
        }
        else if (phase == 3) {
            if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_9) == GPIO_PIN_RESET) {
                printf("distance=%.1f cm\n", (uint32_t)(now - echoStarted) / 58.0);
                phase = 4;
            }
            else if ((uint32_t)(now - started) >= 30000) {
                printf("HC-SR04 timeout\n");
                phase = 4;
            }
        }
        else if (phase == 4 && (uint32_t)(now - started) >= 60000) phase = 0;
        /* USER CODE END 3 */
    }
}

