    transferByte(0);
    transferByte(0);
    transferByte(0);
    transferByte(127);
    tftEnd();
    tftCommand(0x2B);
    transferByte(0);
    transferByte(0);
    transferByte(0);
    transferByte(159);
    tftEnd();
    tftCommand(0x2C);
    for (int y = 0; y < 160; y++) {
        uint8_t row[256];
        for (int x = 0; x < 128; x++) {
            uint16_t color = x < 43 ? 0xF800 : (x < 86 ? 0x07E0 : 0x001F);
            row[x*2] = color >> 8;
            row[x*2+1] = color & 255;
        }
        HAL_SPI_Transmit(&hspi1, row, 256, 100);
        HAL_Delay(1);
