    printf("TFT: initializing RGB565 display\n");
    HAL_GPIO_WritePin(GPIOC, GPIO_PIN_7, GPIO_PIN_RESET);
    HAL_Delay(1);
    HAL_GPIO_WritePin(GPIOC, GPIO_PIN_7, GPIO_PIN_SET);
    HAL_Delay(120);
    tftCommand(0x11);
    tftEnd();
    HAL_Delay(120);
    tftCommand(0x3A);
    transferByte(0x55);
    tftEnd();
    tftCommand(0x29);
    tftEnd();
    tftCommand(0x2A);
    transferByte(0);
    transferByte(0);
    transferByte(0);
    transferByte(127);
    tftEnd();
    tftCommand(0x2B);
    transferByte(0);
    transferByte(0);
    transferByte(0);
    transferByte(159);
    tftEnd();
    tftCommand(0x2C);
    for (int y = 0; y < 160; y++) {
        uint8_t row[256];
