    MX_TIM2_Init();
    MX_USART2_UART_Init();
    /* USER CODE BEGIN 2 */
    HAL_TIM_Base_Start(&htim2);
    /* USER CODE END 2 */
    while (1) {
        /* USER CODE BEGIN 3 */
        uint32_t now = __HAL_TIM_GET_COUNTER(&htim2);
        if (phase == 0) {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_7, GPIO_PIN_SET);
            started = now;
            phase = 1;
        }
        else if (phase == 1 && (uint16_t)(now - started) >= 10) {
            HAL_GPIO_WritePin(GPIOC, GPIO_PIN_7, GPIO_PIN_RESET);
            started = now;
            phase = 2;
        }
        else if (phase == 2) {
            if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_9) == GPIO_PIN_SET) {
                echoStarted = now;
                phase = 3;
            }
            else if ((uint16_t)(now - started) >= 30000) {
                printf("HC-SR04 timeout\n");
                phase = 4;
            }
        }
        else if (phase == 3) {
            if (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_9) == GPIO_PIN_RESET) {
                printf("distance=%.1f cm\n", (uint16_t)(now - echoStarted) / 58.0);
                phase = 4;
            }
            else if ((uint16_t)(now - started) >= 30000) {
                printf("HC-SR04 timeout\n");
                phase = 4;
            }
        }
        else if (phase == 4 && (uint16_t)(now - started) >= 60000) phase = 0;
        /* USER CODE END 3 */
    }
}

